function mex_build_all()
%MEX_BUILD_ALL Compile the common MEX sources used by MIGA
%
%   mex_build_all() will attempt to compile a small set of recommended MEX
%   sources used by the project. It compiles known targets with suggested
%   flags and then tries to compile any remaining .c/.cpp files found under
%   the `tensor/computation` tree. Failures are reported but do not abort the
%   whole process.
%
%   FILE GENERATED BY COPILOT AND ADJUSTED

root = fileparts(fileparts(mfilename('fullpath')));
cd(root)
fprintf('MIGA mex build in: %s\n', root);



targets = {
    struct('path', fullfile(root,'tensor','computation','tSparsityCPP','tSparsityToSparse.cpp'), 'flags', {{'-R2018a','CXXFLAGS=$CXXFLAGS -std=c++20 -Wall -Werror'}})
};

for k = 1:numel(targets)
    t = targets{k};
    if ~isfile(t.path)
        fprintf('  [SKIP] not found: %s\n', t.path);
        continue;
    end
    try
        fprintf('  [BUILD] %s\n', t.path);
        if isempty(t.flags{1})
            mex(t.path);
        else
            mex(t.flags{:}, t.path);
        end
        fprintf('  [OK]    %s\n', t.path);
    catch ME
        if ismac 
            fprintf('  [TRY FIX FOR MAC]  %s\n', t.path);     
            try
                mex(t.flags{:},'LDFLAGS=$LDFLAGS -ld_classic', t.path);
                fprintf('  [OK WITH FIX]    %s\n', t.path);
            catch ME2
                fprintf('  [FAIL STANDARD]  %s -> %s\n [FAIL WITH FIX] %s \n', t.path, ME.message, ME2.message);
            end
        else
            fprintf('  [FAIL]  %s -> %s\n', t.path, ME.message);
        end    
    end
end

fprintf('MIGA mex build finished.\n');
fprintf('If compilation failed for some files, run mex manually with the suggested flags (see Documentation/installation.md).\n');
end
